#include "string.h"
size_t strlen(const char *радок_дадзеныя) { const char *자료위치 = радок_дадзеныя; while (*자료위치) 자료위치++; return 자료위치 - радок_дадзеныя; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *каардыната_x = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*каардыната_x != *세로좌표) return (int)*каардыната_x - *세로좌표; каардыната_x++; 세로좌표++; } return 0; }
void *memmove(void *прызначэнне_дадзеныя, const void *радок_дадзеныя, size_t 개수) { unsigned char *каардыната_x = прызначэнне_дадзеныя; const unsigned char *세로좌표 = радок_дадзеныя; if (каардыната_x < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) каардыната_x[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; каардыната_x[개수] = 세로좌표[개수]; } } return прызначэнне_дадзеныя; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char каардыната_x = *첫째값++, 세로좌표 = *둘째값++; if (каардыната_x != 세로좌표) return (int)каардыната_x-세로좌표; if (!каардыната_x) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *радок_дадзеныя, char **скончыць_Зрух, int Фон_значэнне) {
    const char *Пуск_Зрух = радок_дадзеныя; unsigned long значэнне = 0; int кадаванне_значэнне = 1, 하나라도 = 0;
    while (*радок_дадзеныя == ' ' || (*радок_дадзеныя >= 9 && *радок_дадзеныя <= 13)) радок_дадзеныя++;
    if (*радок_дадзеныя == '-' || *радок_дадзеныя == '+') { if (*радок_дадзеныя == '-') кадаванне_значэнне = -1; радок_дадзеныя++; }
    if (Фон_значэнне == 0) Фон_значэнне = 10;
    while (*радок_дадзеныя >= '0' && *радок_дадзеныя <= '9' && *радок_дадзеныя - '0' < Фон_значэнне) {
        unsigned лічба_значэнне = *радок_дадзеныя++ - '0'; 하나라도 = 1;
        if (значэнне > (0x7ffffffffffffffful - лічба_значэнне) / (unsigned)Фон_значэнне) значэнне = 0x7ffffffffffffffful;
        else значэнне = значэнне * Фон_значэнне + лічба_значэнне;
    }
    if (скончыць_Зрух) *скончыць_Зрух = (char *)(하나라도 ? радок_дадзеныя : Пуск_Зрух); return кадаванне_значэнне > 0 ? (long)значэнне : -(long)значэнне;
}
int atoi(const char *радок_дадзеныя) { return (int)strtol(радок_дадзеныя, 0, 10); }
